(1241594, 158136, 31637, '<td valign="top">wow...good luck</td>', 'wow...good luck', '2005-03-21 18:12:56.000000', NULL, 1),
(1241597, 158155, 33560, '<td valign="top">This is an amazing capture.  I''ve never seen this happen, nor can I remember seeing a photo of it.<br/> <br/>In action photos,I understand that there are severe limitations to the control one has over composition. Bearing that in mind, I find the water line to be too strong. One possibility is to crop it out.  This means clipping the end of one wing, but I think that the photo would be much stronger presented this way and cropped into a vertical format.  Increasing the contrast between subject and water using photoshop might make the image more impactful.</td>', 'This is an amazing capture.  I''ve never seen this happen, nor can I remember seeing a photo of it. In action photos,I understand that there are severe limitations to the control one has over composition. Bearing that in mind, I find the water line to be too strong. One possibility is to crop it out.  This means clipping the end of one wing, but I think that the photo would be much stronger presented this way and cropped into a vertical format.  Increasing the contrast between subject and water using photoshop might make the image more impactful.', '2005-03-21 18:16:47.000000', NULL, 1),
(1241600, 157857, 33560, '<td valign="top">It''s tangled and cluttered, but I like it.</td>', 'It''s tangled and cluttered, but I like it.', '2005-03-21 18:19:04.000000', NULL, 1),
(1241601, 157176, 7599, '<td valign="top">Lovely image, the colours look a little unreal, but still beautiful. I''d be interested to know if this was photoshopped or if I am just missing some amazing sunsets =)</td>', 'Lovely image, the colours look a little unreal, but still beautiful. I''d be interested to know if this was photoshopped or if I am just missing some amazing sunsets =)', '2005-03-21 18:19:26.000000', NULL, 1),
