(1241903, 158068, 32754, '<td valign="top">I like the bottles and the color, but maybe the position is a little awkward..or maybe it''s just me...7</td>', 'I like the bottles and the color, but maybe the position is a little awkward..or maybe it''s just me...7', '2005-03-21 20:24:40.000000', NULL, 1),
(1241907, 157593, 23478, '<td valign="top">Excellent imgae... the lighting is good and the DOF is very nice.</td>', 'Excellent imgae... the lighting is good and the DOF is very nice.', '2005-03-21 20:27:17.000000', NULL, 1),
(1241912, 157375, 33560, '<td valign="top">The lighting looks good and the composition seems interesting.  It appears that the only part of the photo in focus is the reflection of the white king''s crown, and this is simply not enough for my taste. <br/> <br/>Also I''m confused. The focus is on the toppled king. He has presumably lost the battle.  Or is he just reclining comfortably while the other king is bringing him fresh fruits and cheeses?</td>', 'The lighting looks good and the composition seems interesting.  It appears that the only part of the photo in focus is the reflection of the white king''s crown, and this is simply not enough for my taste.  Also I''m confused. The focus is on the toppled king. He has presumably lost the battle.  Or is he just reclining comfortably while the other king is bringing him fresh fruits and cheeses?', '2005-03-21 20:31:03.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1241913, 158043, 23478, '<td valign="top">Any more detail and I would swing at it... Great shot!</td>', 'Any more detail and I would swing at it... Great shot!', '2005-03-21 20:31:23.000000', NULL, 1),
(1241919, 157860, 23478, '<td valign="top">Nice colors.</td>', 'Nice colors.', '2005-03-21 20:33:26.000000', NULL, 1),
(1241920, 157512, 33560, '<td valign="top">Proving once again that dirt can be beautiful.  The color, texture, and line in this photo are exquisite.  (Apropos to nothing; when it''s part of a machine it is known as a helical spring.)</td>', 'Proving once again that dirt can be beautiful.  The color, texture, and line in this photo are exquisite.  (Apropos to nothing; when it''s part of a machine it is known as a helical spring.)', '2005-03-21 20:33:43.000000', NULL, 1),
(1241923, 158069, 23478, '<td valign="top">Nice photo, seems like maybe a tighter crop would create more interest.</td>', 'Nice photo, seems like maybe a tighter crop would create more interest.', '2005-03-21 20:34:37.000000', NULL, 1),
(1241929, 157629, 23478, '<td valign="top">Great shot, is it two children, or one leaning against a mirror?</td>', 'Great shot, is it two children, or one leaning against a mirror?', '2005-03-21 20:36:26.000000', NULL, 1),
(1241932, 157313, 23478, '<td valign="top">The colors here are great, there seems to be a subtle range of tones and hues.  Nice photo!</td>', 'The colors here are great, there seems to be a subtle range of tones and hues.  Nice photo!', '2005-03-21 20:39:30.000000', NULL, 1),
(1241933, 158032, 33560, '<td valign="top">Photos of works of art need to add something to be successful.   Sometimes that is done by skillful observation - editing &amp; cropping, noticing unusual and dramatic lighting conditions and so on.  I find this sculpture to be competently executed but uninspiring piece of art.  And I find the photo of it to be just a little short of that.  It looks a littel unsharp.  And the background seems to be too nearly the color and value of the work.</td>', 'Photos of works of art need to add something to be successful.   Sometimes that is done by skillful observation - editing & cropping, noticing unusual and dramatic lighting conditions and so on.  I find this sculpture to be competently executed but uninspiring piece of art.  And I find the photo of it to be just a little short of that.  It looks a littel unsharp.  And the background seems to be too nearly the color and value of the work.', '2005-03-21 20:40:59.000000', NULL, 1),
(1241937, 157860, 33560, '<td valign="top">This is the best piggybank stock photo of the competition.</td>', 'This is the best piggybank stock photo of the competition.', '2005-03-21 20:43:35.000000', NULL, 1),
(1241940, 157381, 23478, '<td valign="top">WOW,  the detail si stunning as are the background colors.  10.</td>', 'WOW,  the detail si stunning as are the background colors.  10.', '2005-03-21 20:46:00.000000', NULL, 1),
(1241944, 158113, 23478, '<td valign="top">Interesting shot, the colors and shadows all work well.</td>', 'Interesting shot, the colors and shadows all work well.', '2005-03-21 20:47:53.000000', NULL, 1),
(1241945, 157458, 23478, '<td valign="top">Excellent, wonderful shot.</td>', 'Excellent, wonderful shot.', '2005-03-21 20:48:57.000000', NULL, 1),
(1241948, 158181, 23478, '<td valign="top">Excellent tonal range and DOF.</td>', 'Excellent tonal range and DOF.', '2005-03-21 20:50:01.000000', NULL, 1),
(1241951, 157886, 23478, '<td valign="top">Wonderful detail.</td>', 'Wonderful detail.', '2005-03-21 20:51:47.000000', NULL, 1),
(1241954, 158116, 33560, '<td valign="top">This photo has such a strong old world sensibility to it, that I find completely beautiful. I hope it does well.</td>', 'This photo has such a strong old world sensibility to it, that I find completely beautiful. I hope it does well.', '2005-03-21 20:54:00.000000', NULL, 1),
(1241958, 156796, 33560, '<td valign="top">Standing three feet or six feet to either side would put the piers on a diagonal, allowing us to see more of them and making the photo more dynamic.</td>', 'Standing three feet or six feet to either side would put the piers on a diagonal, allowing us to see more of them and making the photo more dynamic.', '2005-03-21 20:55:21.000000', NULL, 1),
(1241959, 157870, 23478, '<td valign="top">Bizarre, with the boat in the center of the photo....  definitely an attention grabber.</td>', 'Bizarre, with the boat in the center of the photo....  definitely an attention grabber.', '2005-03-21 20:55:24.000000', NULL, 1),
