(1242156, 158196, 14735, '<td valign="top">THe light seems a bit bright on the fingers. I like the composition. 7</td>', 'THe light seems a bit bright on the fingers. I like the composition. 7', '2005-03-21 22:35:58.000000', NULL, 1),
