(1244276, 157860, 4226, '<td valign="top">Yes great stock photo</td>', 'Yes great stock photo', '2005-03-22 23:55:43.000000', NULL, 1),
(1244277, 157937, 34396, '<td valign="top">I know this is picky, but I don''t like the rust on the paintbrush.  Everything else looks new and could be an ad for a paint store.  Would have scored it up a point or two if the paintbrush had been new.</td>', 'I know this is picky, but I don''t like the rust on the paintbrush.  Everything else looks new and could be an ad for a paint store.  Would have scored it up a point or two if the paintbrush had been new.', '2005-03-22 23:55:46.000000', NULL, 1),
(1244278, 157397, 34396, '<td valign="top">Cropped a bit too close at the bottom for me.</td>', 'Cropped a bit too close at the bottom for me.', '2005-03-22 23:56:30.000000', NULL, 1),
(1244279, 158001, 4226, '<td valign="top">the aquarium glass doesn''t look like that transparent... you lose some sharpness because of that.. otherwise good image</td>', 'the aquarium glass doesn''t look like that transparent... you lose some sharpness because of that.. otherwise good image', '2005-03-22 23:57:18.000000', NULL, 1),
