INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1244283, 156876, 34396, '<td valign="top">Colorful, well lit shot.</td>', 'Colorful, well lit shot.', '2005-03-22 23:58:03.000000', NULL, 1),
(1244286, 158135, 34396, '<td valign="top">Too small, I cant tell what it is supposed to be.  Colors seem washed out.</td>', 'Too small, I cant tell what it is supposed to be.  Colors seem washed out.', '2005-03-22 23:59:10.000000', NULL, 1),
(1244288, 158041, 34396, '<td valign="top">Another vacation photo.  Not enough interest.</td>', 'Another vacation photo.  Not enough interest.', '2005-03-22 23:59:49.000000', NULL, 1),
(1244289, 158188, 4226, '<td valign="top">somehow the eyes look too much dodged..looks overdone</td>', 'somehow the eyes look too much dodged..looks overdone', '2005-03-22 23:59:58.000000', NULL, 1),
(1244291, 157359, 34069, '<td valign="top">A nice arrangement but I just don''t like the lighting.  Maybe a little brighter overall would help.</td>', 'A nice arrangement but I just don''t like the lighting.  Maybe a little brighter overall would help.', '2005-03-23 00:00:45.000000', NULL, 1),
(1244297, 157660, 34069, '<td valign="top">Too many light and shadowed areas in the background distract me from the subject.</td>', 'Too many light and shadowed areas in the background distract me from the subject.', '2005-03-23 00:01:59.000000', NULL, 1),
(1244300, 157965, 34069, '<td valign="top">This would be a good stock subject but I think there''s too much glare.</td>', 'This would be a good stock subject but I think there''s too much glare.', '2005-03-23 00:02:42.000000', NULL, 1),
(1244307, 157868, 34069, '<td valign="top">The reflection on the right side of the bottle is distracting and I think in general the color looks a bit washed out.</td>', 'The reflection on the right side of the bottle is distracting and I think in general the color looks a bit washed out.', '2005-03-23 00:03:54.000000', NULL, 1),
(1244313, 157739, 34069, '<td valign="top">I like the tree ring theme but would have cleaned off the bird dropping and cropped out more of the background.</td>', 'I like the tree ring theme but would have cleaned off the bird dropping and cropped out more of the background.', '2005-03-23 00:04:56.000000', NULL, 1),
(1244316, 157291, 34069, '<td valign="top">I think the focus is not sharp enough and the interior of the PC looks a bit hazy.</td>', 'I think the focus is not sharp enough and the interior of the PC looks a bit hazy.', '2005-03-23 00:05:42.000000', NULL, 1),
(1244319, 157633, 34396, '<td valign="top">Something not quite right with background.  Bananna''s don''t seem to have enough impact?  Photo looks flat.</td>', 'Something not quite right with background.  Bananna''s don''t seem to have enough impact?  Photo looks flat.', '2005-03-23 00:06:36.000000', NULL, 1),
(1244324, 157352, 34069, '<td valign="top">It''s certainly camouflaged.  But too much so for me; the whole thing tends to fade into a greenish blur.</td>', 'It''s certainly camouflaged.  But too much so for me; the whole thing tends to fade into a greenish blur.', '2005-03-23 00:07:02.000000', NULL, 1),
(1244326, 158048, 34069, '<td valign="top">I would make it bigger; I don''t think you''ve used the whole 640 pixels available.</td>', 'I would make it bigger; I don''t think you''ve used the whole 640 pixels available.', '2005-03-23 00:07:43.000000', NULL, 1),
(1244328, 158162, 34396, '<td valign="top">Cute idea, Could have used a bit more contrast.  Hat blends into background.</td>', 'Cute idea, Could have used a bit more contrast.  Hat blends into background.', '2005-03-23 00:08:15.000000', NULL, 1),
(1244332, 156124, 34069, '<td valign="top">I wish the glass didn''t disappear into the background quite as much.  Maybe a black background?</td>', 'I wish the glass didn''t disappear into the background quite as much.  Maybe a black background?', '2005-03-23 00:09:28.000000', NULL, 1),
(1244335, 158075, 34069, '<td valign="top">Beautiful.  I like the colors; like the composition,like the detail in the foreground.  The clouds are cool, too.</td>', 'Beautiful.  I like the colors; like the composition,like the detail in the foreground.  The clouds are cool, too.', '2005-03-23 00:10:57.000000', NULL, 1),
(1244339, 157291, 34396, '<td valign="top">Shouldn''t those cables be a little neater?  I like the lighting of this photo.</td>', 'Shouldn''t those cables be a little neater?  I like the lighting of this photo.', '2005-03-23 00:11:35.000000', NULL, 1),
(1244343, 157584, 34069, '<td valign="top">This is a good scene to start with.  I like the framing of the mountains.  Very good DOF.  How did you get such a haze-free  view into the distance?</td>', 'This is a good scene to start with.  I like the framing of the mountains.  Very good DOF.  How did you get such a haze-free  view into the distance?', '2005-03-23 00:12:27.000000', NULL, 1),
(1244349, 158191, 34396, '<td valign="top">Well lit, crisp shot.</td>', 'Well lit, crisp shot.', '2005-03-23 00:13:37.000000', NULL, 1),
(1244350, 157275, 34396, '<td valign="top">Nice lighting!</td>', 'Nice lighting!', '2005-03-23 00:13:58.000000', NULL, 1),
(1244353, 157379, 34396, '<td valign="top">Very nice!</td>', 'Very nice!', '2005-03-23 00:14:31.000000', NULL, 1),
(1244354, 158133, 34069, '<td valign="top">Cool.  Not sure if I would have edited out the scratches in the vase or not.  I like to just sit and stare at this one.</td>', 'Cool.  Not sure if I would have edited out the scratches in the vase or not.  I like to just sit and stare at this one.', '2005-03-23 00:14:50.000000', NULL, 1),
(1244358, 156886, 34069, '<td valign="top">Although the subject doesn''t really appeal to me, I think it is technically good and would be sellable, so I''m voting it highly.  The only thing I would change would be to use a non-black bag on the right.  It kind of gets lost in the background.</td>', 'Although the subject doesn''t really appeal to me, I think it is technically good and would be sellable, so I''m voting it highly.  The only thing I would change would be to use a non-black bag on the right.  It kind of gets lost in the background.', '2005-03-23 00:17:20.000000', NULL, 1),
(1244365, 157865, 34069, '<td valign="top">I really like this.  Everything about it says "bleak" - the color, the subject, the dried mud in the foreground.  Is that a dust storm on the horizon, or is it clouds or fog?</td>', 'I really like this.  Everything about it says "bleak" - the color, the subject, the dried mud in the foreground.  Is that a dust storm on the horizon, or is it clouds or fog?', '2005-03-23 00:19:23.000000', NULL, 1),
(1244372, 156032, 34069, '<td valign="top">The wave and surfer are beautiful.  I like the lighting angle.  The sky looks overprocessed to me.</td>', 'The wave and surfer are beautiful.  I like the lighting angle.  The sky looks overprocessed to me.', '2005-03-23 00:20:57.000000', NULL, 1),
(1244379, 157881, 34069, '<td valign="top">Goofy title but  great image.</td>', 'Goofy title but  great image.', '2005-03-23 00:22:25.000000', NULL, 1),
(1244388, 157971, 34069, '<td valign="top">I like this one.  The top of the coffeepot is a bit bright for me, and the front edge too dark.  It seems to get lost in the background.</td>', 'I like this one.  The top of the coffeepot is a bit bright for me, and the front edge too dark.  It seems to get lost in the background.', '2005-03-23 00:24:02.000000', NULL, 1),
(1244396, 158045, 34396, '<td valign="top">I like the background on this image.  Very nice lighting!</td>', 'I like the background on this image.  Very nice lighting!', '2005-03-23 00:25:05.000000', NULL, 1),
(1244406, 157873, 34069, '<td valign="top">Great skin tone, I especially like how you got the film of water on the kid without any glare.  Librodo?</td>', 'Great skin tone, I especially like how you got the film of water on the kid without any glare.  Librodo?', '2005-03-23 00:26:21.000000', NULL, 1),
(1244409, 157950, 34396, '<td valign="top">Too dark, not enough contrast.</td>', 'Too dark, not enough contrast.', '2005-03-23 00:26:39.000000', NULL, 1),
(1244411, 157240, 34069, '<td valign="top">I like the color in this but somehow the image seems very "flat".  Maybe I''d have shot it from an angle other than straight overhead.</td>', 'I like the color in this but somehow the image seems very "flat".  Maybe I''d have shot it from an angle other than straight overhead.', '2005-03-23 00:27:24.000000', NULL, 1),
(1244424, 157452, 34069, '<td valign="top">I think I''ve seen this castle before, but I really like the way the person seems to be staring up at it.</td>', 'I think I''ve seen this castle before, but I really like the way the person seems to be staring up at it.', '2005-03-23 00:28:39.000000', NULL, 1),
(1244429, 157381, 34396, '<td valign="top">I think this could use a bit more contrast? or brighter?  The photo seems to have a greyish cast to me.</td>', 'I think this could use a bit more contrast? or brighter?  The photo seems to have a greyish cast to me.', '2005-03-23 00:29:19.000000', NULL, 1),
(1244432, 156608, 34069, '<td valign="top">An unusual angle to shoot from.  I''m not sure if I like it or dislike it.  It''s interesting but gives me almost a feeling of vertigo.</td>', 'An unusual angle to shoot from.  I''m not sure if I like it or dislike it.  It''s interesting but gives me almost a feeling of vertigo.', '2005-03-23 00:30:14.000000', NULL, 1),
(1244434, 157535, 34396, '<td valign="top">Hard to tell what you were focusing on here. I think it would have had more impact if the focus point had been the lettering in the lens.</td>', 'Hard to tell what you were focusing on here. I think it would have had more impact if the focus point had been the lettering in the lens.', '2005-03-23 00:30:24.000000', NULL, 1),
(1244438, 156837, 34396, '<td valign="top">You sold me.  I like the softness of this photo.</td>', 'You sold me.  I like the softness of this photo.', '2005-03-23 00:31:03.000000', NULL, 1),
(1244442, 157359, 34396, '<td valign="top">Sorry, don''t care for the red tones on this one.</td>', 'Sorry, don''t care for the red tones on this one.', '2005-03-23 00:31:31.000000', NULL, 1),
(1244444, 157593, 34069, '<td valign="top">The coloration gives this ball more character then most baseball shots I''ve seen.  I just wish there wasn''t so much of a shadow.</td>', 'The coloration gives this ball more character then most baseball shots I''ve seen.  I just wish there wasn''t so much of a shadow.', '2005-03-23 00:31:49.000000', NULL, 1),
(1244451, 158161, 34396, '<td valign="top">Not interesting enough.  Just looks like a closeup shot of a garbage can.</td>', 'Not interesting enough.  Just looks like a closeup shot of a garbage can.', '2005-03-23 00:32:13.000000', NULL, 1),
(1244454, 158173, 34069, '<td valign="top">I would like to see the right side of the cup lit up a bit more.  Otherwise a good shot.</td>', 'I would like to see the right side of the cup lit up a bit more.  Otherwise a good shot.', '2005-03-23 00:32:49.000000', NULL, 1),
(1244455, 157593, 34396, '<td valign="top">Not bad.  Lighting seems a bit bright on the right side.</td>', 'Not bad.  Lighting seems a bit bright on the right side.', '2005-03-23 00:32:50.000000', NULL, 1),
(1244459, 157360, 34396, '<td valign="top">Over lit, not interesting.</td>', 'Over lit, not interesting.', '2005-03-23 00:33:20.000000', NULL, 1),
(1244468, 157886, 34069, '<td valign="top">This is neat.  I don''t like the reflections in the ball, though.  If you can''t elminate them maybe they could be used to advantage - perhaps just the photographer in front of a featureless wall?</td>', 'This is neat.  I don''t like the reflections in the ball, though.  If you can''t elminate them maybe they could be used to advantage - perhaps just the photographer in front of a featureless wall?', '2005-03-23 00:34:21.000000', NULL, 1),
(1244470, 158200, 34396, '<td valign="top">I don''t care for the cropping on this shot.</td>', 'I don''t care for the cropping on this shot.', '2005-03-23 00:34:43.000000', NULL, 1),
(1244471, 156844, 34069, '<td valign="top">This is pretty but having seen sharper ones like this on here before make me less impressed.</td>', 'This is pretty but having seen sharper ones like this on here before make me less impressed.', '2005-03-23 00:35:21.000000', NULL, 1),
(1244474, 158079, 34396, '<td valign="top">Don''t care for the colors on this photo.</td>', 'Don''t care for the colors on this photo.', '2005-03-23 00:36:07.000000', NULL, 1),
