(1245409, 157735, 34396, '<td valign="top">Needs more contrast in the sky.</td>', 'Needs more contrast in the sky.', '2005-03-23 12:37:27.000000', NULL, 1),
(1245412, 158176, 34396, '<td valign="top">Nice lighting.</td>', 'Nice lighting.', '2005-03-23 12:38:12.000000', NULL, 1),
(1245413, 158020, 13305, '<td valign="top">Not bad composition, but I think slightly less blur with a slightly higher shutter speed would be more effective.  Keep on trying.</td>', 'Not bad composition, but I think slightly less blur with a slightly higher shutter speed would be more effective.  Keep on trying.', '2005-03-23 12:38:14.000000', NULL, 1),
(1245414, 157975, 34396, '<td valign="top">I think for this kind of shot to work, it either needs no shadows or a very dramatic shadow.  This has an average shadow and looks a bit faded to me.</td>', 'I think for this kind of shot to work, it either needs no shadows or a very dramatic shadow.  This has an average shadow and looks a bit faded to me.', '2005-03-23 12:39:30.000000', NULL, 1),
(1245416, 157887, 13305, '<td valign="top">Almost like a postcard but a little too much sky for this composition.  Excellent focus and tones.</td>', 'Almost like a postcard but a little too much sky for this composition.  Excellent focus and tones.', '2005-03-23 12:39:52.000000', NULL, 1),
(1245418, 157897, 34396, '<td valign="top">Photo is not sharp, sky looks washed out.</td>', 'Photo is not sharp, sky looks washed out.', '2005-03-23 12:40:30.000000', NULL, 1),
(1245421, 158136, 34396, '<td valign="top">Most of the picture is too out of focus for me.  Without the title, I would not have been able to figure out what this picture is about.</td>', 'Most of the picture is too out of focus for me.  Without the title, I would not have been able to figure out what this picture is about.', '2005-03-23 12:41:45.000000', NULL, 1),
(1245423, 158183, 13305, '<td valign="top">Interesting specimen.  I''d like to be able to see the entire length of the spiders legs instead of having them run off the frame.</td>', 'Interesting specimen.  I''d like to be able to see the entire length of the spiders legs instead of having them run off the frame.', '2005-03-23 12:42:40.000000', NULL, 1),
(1245425, 157420, 34396, '<td valign="top">I like the clarity of the moon itself.  I would be really interested to know what equipment was used for this shot.  That said, the background really ruins the photo.  There seems to be lots of noise.  Could this have been cleaned up with a filter?</td>', 'I like the clarity of the moon itself.  I would be really interested to know what equipment was used for this shot.  That said, the background really ruins the photo.  There seems to be lots of noise.  Could this have been cleaned up with a filter?', '2005-03-23 12:43:22.000000', NULL, 1),
(1245426, 157398, 34396, '<td valign="top">I for one never tire of stunning sunsets!  Very nice!</td>', 'I for one never tire of stunning sunsets!  Very nice!', '2005-03-23 12:43:58.000000', NULL, 1),
(1245431, 158154, 34396, '<td valign="top">Love the capture, would have liked to see the entire ear in the final photo however.</td>', 'Love the capture, would have liked to see the entire ear in the final photo however.', '2005-03-23 12:44:36.000000', NULL, 1),
(1245433, 157881, 13305, '<td valign="top">Good focus and saturation, but I''m inclined to agree with your title.</td>', 'Good focus and saturation, but I''m inclined to agree with your title.', '2005-03-23 12:44:38.000000', NULL, 1),
(1245436, 157458, 34396, '<td valign="top">Another beautiful sunset.  Edges of cactus look a bit pixelized to me.</td>', 'Another beautiful sunset.  Edges of cactus look a bit pixelized to me.', '2005-03-23 12:45:44.000000', NULL, 1),
(1245439, 157240, 34396, '<td valign="top">Bright, vibrant colors.</td>', 'Bright, vibrant colors.', '2005-03-23 12:47:17.000000', NULL, 1),
(1245440, 156686, 13305, '<td valign="top">Great picture considering the speed at which you had to pan to get it.  Very dynamic image.  I give you a nine for the effort.</td>', 'Great picture considering the speed at which you had to pan to get it.  Very dynamic image.  I give you a nine for the effort.', '2005-03-23 12:47:28.000000', NULL, 1),
