(1245454, 157172, 13305, '<td valign="top">Interesting image, but it gives me a headache.  Try throwing alkaseltzer in the glass to add interest.</td>', 'Interesting image, but it gives me a headache.  Try throwing alkaseltzer in the glass to add interest.', '2005-03-23 12:51:49.000000', NULL, 1),
