(1245544, 158197, 34396, '<td valign="top">I don''t care for shadows in this type of shot.  also focus seems a bit soft on back edges of cup.</td>', 'I don''t care for shadows in this type of shot.  also focus seems a bit soft on back edges of cup.', '2005-03-23 13:16:24.000000', NULL, 1),
(1245550, 157661, 30049, '<td valign="top">Absolutely gorgeous!  A ribbon here for sure - great shot! 10</td>', 'Absolutely gorgeous!  A ribbon here for sure - great shot! 10', '2005-03-23 13:17:52.000000', NULL, 1),
(1245556, 157886, 34396, '<td valign="top">This photo must have taken quite a bit of time to get right.  The reflections of you in the bubble are a bit distracting to me.  The small blob on the base of the left pushpin is also a bit distracting.</td>', 'This photo must have taken quite a bit of time to get right.  The reflections of you in the bubble are a bit distracting to me.  The small blob on the base of the left pushpin is also a bit distracting.', '2005-03-23 13:19:55.000000', NULL, 1),
(1245563, 158062, 34396, '<td valign="top">Not a bad shot.  I can''t put my finger on it, but the photo lacks "Punch"</td>', 'Not a bad shot.  I can''t put my finger on it, but the photo lacks "Punch"', '2005-03-23 13:21:18.000000', NULL, 1),
(1245564, 157654, 30049, '<td valign="top">The color, clarity, and contrast of the squirrel and leaves-dirt-branches is wonderful!  I hope this image gets the credit it deserves.  The only negative I can see is a minor bit of noise in the background leaves (from zoom length perhaps?).  Great job! 10</td>', 'The color, clarity, and contrast of the squirrel and leaves-dirt-branches is wonderful!  I hope this image gets the credit it deserves.  The only negative I can see is a minor bit of noise in the background leaves (from zoom length perhaps?).  Great job! 10', '2005-03-23 13:21:28.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1245568, 157366, 4517, '<td valign="top">Good advertisment shot but not a stock photo. Unless you mean beef stock :)</td>', 'Good advertisment shot but not a stock photo. Unless you mean beef stock :)', '2005-03-23 13:22:26.000000', NULL, 1),
