(1245603, 157420, 4517, '<td valign="top">The photo is well taken with good focus and exposure but needs a bit more work in ps. The background should be jet black and the moon needs more contrast and sharpening. Still a 7.</td>', 'The photo is well taken with good focus and exposure but needs a bit more work in ps. The background should be jet black and the moon needs more contrast and sharpening. Still a 7.', '2005-03-23 13:36:44.000000', NULL, 1),
(1245632, 157938, 22872, '<td valign="top">I like the photo...wish you could have gotten that little twig out from in front of the bird....easier said than done :)</td>', 'I like the photo...wish you could have gotten that little twig out from in front of the bird....easier said than done :)', '2005-03-23 13:45:27.000000', NULL, 1),
