(1245669, 158187, 22872, '<td valign="top">love the contrasting colors...  looking from the bottom is appears to be rotated correctly but when you move your eyes upward it seems a little cockeyed?</td>', 'love the contrasting colors...  looking from the bottom is appears to be rotated correctly but when you move your eyes upward it seems a little cockeyed?', '2005-03-23 13:57:43.000000', NULL, 1),
(1245671, 156895, 6008, '<td valign="top">Looks a tad soft and although you have the diagonal thing going it seems a little haphazard in composition. The isolated background is good.</td>', 'Looks a tad soft and although you have the diagonal thing going it seems a little haphazard in composition. The isolated background is good.', '2005-03-23 13:58:14.000000', NULL, 1),
(1245674, 158113, 22872, '<td valign="top">I like the composition of this....is it a little soft?  I''m on a laptop so that may be it...</td>', 'I like the composition of this....is it a little soft?  I''m on a laptop so that may be it...', '2005-03-23 13:59:06.000000', NULL, 1),
