(1249246, 158155, 6668, '<td valign="top">great capture..nicely done!</td>', 'great capture..nicely done!', '2005-03-25 09:18:21.000000', NULL, 1),
(1249249, 157394, 33924, '<td valign="top">The colors are quite nice and the depth of field is also effective, though I''m not sure it would be a highly sellable photo due to it''s subject material.</td>', 'The colors are quite nice and the depth of field is also effective, though I''m not sure it would be a highly sellable photo due to it''s subject material.', '2005-03-25 09:19:14.000000', NULL, 1),
(1249253, 157889, 33924, '<td valign="top">The simplicity of your subject choice is nice and the color of the strawberry makes it look very tasty. I think, though, that trying out different kinds of lighting might enhance the gorgeousness of the strawberry. The flash casts shadows that aren''t particularly complimentary as well as a bit of a glare.</td>', 'The simplicity of your subject choice is nice and the color of the strawberry makes it look very tasty. I think, though, that trying out different kinds of lighting might enhance the gorgeousness of the strawberry. The flash casts shadows that aren''t particularly complimentary as well as a bit of a glare.', '2005-03-25 09:22:16.000000', NULL, 1),
(1249385, 157202, 23278, '<td valign="top">Nice, but too cluttered.</td>', 'Nice, but too cluttered.', '2005-03-25 11:55:12.000000', NULL, 1),
