(1250092, 157864, 12674, '<td valign="top">I might''ve rotated slightly to achieve true vertical...also a little dark on top and lighting a bit bright at bottom</td>', 'I might''ve rotated slightly to achieve true vertical...also a little dark on top and lighting a bit bright at bottom', '2005-03-25 22:38:05.000000', NULL, 1),
(1250095, 158054, 12674, '<td valign="top">Unusual subject, good idea...red seems a little too saturated.  Nice shot though.</td>', 'Unusual subject, good idea...red seems a little too saturated.  Nice shot though.', '2005-03-25 22:41:20.000000', NULL, 1),
(1250097, 157122, 12674, '<td valign="top">Nice composition...seems a tad purply-blue.</td>', 'Nice composition...seems a tad purply-blue.', '2005-03-25 22:42:37.000000', NULL, 1),
(1250099, 157899, 12674, '<td valign="top">A crop around the two red engines to eliminate the pallets might''ve been interesting too. The pallets are a little distracting, but I like the subject a lot.</td>', 'A crop around the two red engines to eliminate the pallets might''ve been interesting too. The pallets are a little distracting, but I like the subject a lot.', '2005-03-25 22:44:35.000000', NULL, 1),
(1250103, 158049, 12674, '<td valign="top">Nice action, great color.  You might try Neat Image to smooth some of the graininess in the sky.</td>', 'Nice action, great color.  You might try Neat Image to smooth some of the graininess in the sky.', '2005-03-25 22:49:45.000000', NULL, 1),
(1250112, 157420, 12674, '<td valign="top">Outstanding shot...and I learned a new word!</td>', 'Outstanding shot...and I learned a new word!', '2005-03-25 22:57:41.000000', NULL, 1),
(1250118, 158173, 12674, '<td valign="top">Nice color and contrast, I like the browniness of the steam, great title!</td>', 'Nice color and contrast, I like the browniness of the steam, great title!', '2005-03-25 22:59:21.000000', NULL, 1),
(1250120, 156686, 12674, '<td valign="top">Wow....they posed for you perfectly. Nice shot!</td>', 'Wow....they posed for you perfectly. Nice shot!', '2005-03-25 23:00:07.000000', NULL, 1),
(1250122, 157595, 12674, '<td valign="top">Justin needs a comb....interesting angle accentuated by the lines of the blinds or curtains.</td>', 'Justin needs a comb....interesting angle accentuated by the lines of the blinds or curtains.', '2005-03-25 23:01:41.000000', NULL, 1),
(1250129, 156468, 12674, '<td valign="top">White hind quarters detract a bit....a crop around that goat''s head expression might''ve been interesting too.  Nice shot.</td>', 'White hind quarters detract a bit....a crop around that goat''s head expression might''ve been interesting too.  Nice shot.', '2005-03-25 23:06:56.000000', NULL, 1),
(1250130, 156662, 12674, '<td valign="top">Unusual angle, piercing stare...nice shot!</td>', 'Unusual angle, piercing stare...nice shot!', '2005-03-25 23:08:27.000000', NULL, 1),
(1250131, 158163, 12674, '<td valign="top">Now there''s something you don''t see every day</td>', 'Now there''s something you don''t see every day', '2005-03-25 23:10:44.000000', NULL, 1),
(1250133, 157870, 13305, '<td valign="top">Nice shot, but I think it would be better if you include it in less foreground or if you lowered your camera closer to the ground.</td>', 'Nice shot, but I think it would be better if you include it in less foreground or if you lowered your camera closer to the ground.', '2005-03-25 23:11:48.000000', NULL, 1),
(1250135, 157857, 13305, '<td valign="top">Good view of the moon.  But next time, crop in closer.  So many branches distracts from the focus of your photo.</td>', 'Good view of the moon.  But next time, crop in closer.  So many branches distracts from the focus of your photo.', '2005-03-25 23:13:30.000000', NULL, 1),
(1250136, 158132, 12674, '<td valign="top">Nice wintry color and feel.  I find the road a little distracting.</td>', 'Nice wintry color and feel.  I find the road a little distracting.', '2005-03-25 23:14:27.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1250139, 158177, 13305, '<td valign="top">Good effort.  I think you were trying to go for a bokeh effect.  You didn''t quite succeed.  Try to get the entire adapter and focus and the cord from the red plug to the edge of the frame out of focus.  Actually, for this challenge, you could''ve had the entire image in focus and been very acceptable.</td>', 'Good effort.  I think you were trying to go for a bokeh effect.  You didn''t quite succeed.  Try to get the entire adapter and focus and the cord from the red plug to the edge of the frame out of focus.  Actually, for this challenge, you could''ve had the entire image in focus and been very acceptable.', '2005-03-25 23:18:43.000000', NULL, 1),
(1250142, 157873, 13305, '<td valign="top">Nice image.  I don''t believe there''s anything I can criticize about this picture.  So don''t change a thing!  10</td>', 'Nice image.  I don''t believe there''s anything I can criticize about this picture.  So don''t change a thing!  10', '2005-03-25 23:22:14.000000', NULL, 1),
(1250143, 157584, 32732, '<td valign="top">awesome!  great depth of feild,  love the mountains in the background!  good job~!</td>', 'awesome!  great depth of feild,  love the mountains in the background!  good job~!', '2005-03-25 23:23:12.000000', NULL, 1),
(1250145, 158080, 32732, '<td valign="top">love this pic.  perfect focus, sharp and crisp.  very clean pic!</td>', 'love this pic.  perfect focus, sharp and crisp.  very clean pic!', '2005-03-25 23:25:06.000000', NULL, 1),
(1250146, 157451, 13305, '<td valign="top">Good effort.  The fact that half the birds face is in shadow makes this picture hard to interpret.  Try treating your subject as if it were a portrait and use a two thirds view from one side or the other.  That will show more detail of the bird and a lot more interest to your viewer.</td>', 'Good effort.  The fact that half the birds face is in shadow makes this picture hard to interpret.  Try treating your subject as if it were a portrait and use a two thirds view from one side or the other.  That will show more detail of the bird and a lot more interest to your viewer.', '2005-03-25 23:26:07.000000', NULL, 1),
(1250155, 157388, 13305, '<td valign="top">Excellent photographic technique.  Good focus color balance and the horizon is straight.  I think that I might have lowered my viewpoint, closer to the sand.  Keep on working!</td>', 'Excellent photographic technique.  Good focus color balance and the horizon is straight.  I think that I might have lowered my viewpoint, closer to the sand.  Keep on working!', '2005-03-25 23:40:09.000000', NULL, 1),
(1250156, 158116, 13305, '<td valign="top">Excellent!  Very evocative of a long time ago.  I even like the frame.  Keep up the good work!  10</td>', 'Excellent!  Very evocative of a long time ago.  I even like the frame.  Keep up the good work!  10', '2005-03-25 23:43:50.000000', NULL, 1),
(1250164, 158000, 13305, '<td valign="top">Check out the rule of thirds and reshoot otherwise, good photo.</td>', 'Check out the rule of thirds and reshoot otherwise, good photo.', '2005-03-25 23:51:58.000000', NULL, 1),
