(1250473, 156427, 20462, '<td valign="top">your one creepy dude. and creative/original.</td>', 'your one creepy dude. and creative/original.', '2005-03-26 10:22:40.000000', NULL, 1),
(1250475, 158183, 2022, '<td valign="top">What I see here is I think a spider, or some other kind of creature. I am not sure how the picture relates to the title. What is incomplete ? What is broken ? The connection is probably there, I just do not see it. I think that picture itself shoould be powerful enough to convey the idea intended, the title should not have to explain the idea. In this particular case not only the title does not explain much, it just adds to the confusion. Sorry, just the way I see it (or don''t). (4)</td>', 'What I see here is I think a spider, or some other kind of creature. I am not sure how the picture relates to the title. What is incomplete ? What is broken ? The connection is probably there, I just do not see it. I think that picture itself shoould be powerful enough to convey the idea intended, the title should not have to explain the idea. In this particular case not only the title does not explain much, it just adds to the confusion. Sorry, just the way I see it (or don''t). (4)', '2005-03-26 10:24:29.000000', NULL, 1),
(1250480, 157331, 25232, '<td valign="top">A wider lens would have helped this shot.</td>', 'A wider lens would have helped this shot.', '2005-03-26 10:32:25.000000', NULL, 1),
