(1251836, 157975, 19936, '<td valign="top">Nice.  Very soft and great white background.  A littel harsh on the side light.</td>', 'Nice.  Very soft and great white background.  A littel harsh on the side light.', '2005-03-27 00:44:33.000000', NULL, 1),
(1251837, 158191, 19936, '<td valign="top">This is a great shot.  Clean, sharp and pointed.  Great for stock.  I think I may not have burned the corners though.  Good job.</td>', 'This is a great shot.  Clean, sharp and pointed.  Great for stock.  I think I may not have burned the corners though.  Good job.', '2005-03-27 00:46:15.000000', NULL, 1),
(1251839, 157397, 19936, '<td valign="top">Good capture.  You got all the colors and kept it a simple composition for stock.  Good job.</td>', 'Good capture.  You got all the colors and kept it a simple composition for stock.  Good job.', '2005-03-27 00:47:28.000000', NULL, 1),
(1251841, 157179, 32997, '<td valign="top">Wonderful shot-i love the green on green..excellent composition,,  where you placed the subject, it gives the whole thing a great context.</td>', 'Wonderful shot-i love the green on green..excellent composition,,  where you placed the subject, it gives the whole thing a great context.', '2005-03-27 00:48:04.000000', NULL, 1),
(1251843, 157378, 19936, '<td valign="top">Great expression.  So happy!  Nice job on the exposure.</td>', 'Great expression.  So happy!  Nice job on the exposure.', '2005-03-27 00:48:56.000000', NULL, 1),
(1251846, 156171, 32997, '<td valign="top">Beautiful lighting, great composition.</td>', 'Beautiful lighting, great composition.', '2005-03-27 00:50:43.000000', NULL, 1),
(1251848, 157600, 19936, '<td valign="top">Wonderful look.  Got to love those eyes.  Good hair highlights but the skin is a bit overexposed for my liking.  Even so, good job overall.</td>', 'Wonderful look.  Got to love those eyes.  Good hair highlights but the skin is a bit overexposed for my liking.  Even so, good job overall.', '2005-03-27 00:51:22.000000', NULL, 1),
(1251850, 158164, 19936, '<td valign="top">Whoa!  Great job on this exposure.</td>', 'Whoa!  Great job on this exposure.', '2005-03-27 00:51:59.000000', NULL, 1),
(1251851, 157881, 19936, '<td valign="top">Such a patriot duck (if he lives in th US that is).  Very crisp and good exposure.</td>', 'Such a patriot duck (if he lives in th US that is).  Very crisp and good exposure.', '2005-03-27 00:52:55.000000', NULL, 1),
(1251853, 158079, 19936, '<td valign="top">The concept here could have been good.  It loses out due to focus and exposure issues.</td>', 'The concept here could have been good.  It loses out due to focus and exposure issues.', '2005-03-27 00:54:33.000000', NULL, 1),
(1251854, 158102, 19936, '<td valign="top">This could be improved with better light so you don''t have the shadows off to the side and a bit better focus.</td>', 'This could be improved with better light so you don''t have the shadows off to the side and a bit better focus.', '2005-03-27 00:56:22.000000', NULL, 1),
(1251855, 158074, 19936, '<td valign="top">Very cute.  I missed this the first time through.  Still, for Stock I think it lacks punch.</td>', 'Very cute.  I missed this the first time through.  Still, for Stock I think it lacks punch.', '2005-03-27 00:57:55.000000', NULL, 1),
(1251859, 158162, 19936, '<td valign="top">Hmmm.  I think for stock photog this one would suffer from the PC police.  Good portrait though,</td>', 'Hmmm.  I think for stock photog this one would suffer from the PC police.  Good portrait though,', '2005-03-27 00:59:26.000000', NULL, 1),
(1251862, 158098, 19936, '<td valign="top">I''m boosting this one up.  On the second pass it jumped out at me.  Not sure if it would sell as stock but it is a great shot.</td>', 'I''m boosting this one up.  On the second pass it jumped out at me.  Not sure if it would sell as stock but it is a great shot.', '2005-03-27 02:01:39.000000', NULL, 1),
(1251868, 157857, 19936, '<td valign="top">I don''t see this one.  Everything is blue but the moon.  Am I to literal?  Anyway this would have been a better shot if the you exposed for the moon so it had a little definition.  That would punch it up a little.  Good luck.</td>', 'I don''t see this one.  Everything is blue but the moon.  Am I to literal?  Anyway this would have been a better shot if the you exposed for the moon so it had a little definition.  That would punch it up a little.  Good luck.', '2005-03-27 02:04:39.000000', NULL, 1),
(1251871, 157262, 19936, '<td valign="top">Another shot that jumped out at me on the second pass through.  Don''t know how I missed it,  Very good Stock shot with great simplicity and carried off well.</td>', 'Another shot that jumped out at me on the second pass through.  Don''t know how I missed it,  Very good Stock shot with great simplicity and carried off well.', '2005-03-27 02:06:31.000000', NULL, 1),
(1251874, 158158, 19936, '<td valign="top">Great composition and carried off well with good focus and exposure.  I''m moving this one up.</td>', 'Great composition and carried off well with good focus and exposure.  I''m moving this one up.', '2005-03-27 02:07:39.000000', NULL, 1),
(1251878, 158165, 19936, '<td valign="top">Looks candid.  Great job.  Well exposed and framed with perfect DOF.</td>', 'Looks candid.  Great job.  Well exposed and framed with perfect DOF.', '2005-03-27 02:09:47.000000', NULL, 1),
