(1252789, 156837, 22781, '<td valign="top">I love the shadow and the highlights.<br/>Sensual, pleasing, technicaly 100% IMHO.<br/>Going into my favs...<br/>Sorry I cant vote 11 so you have to do with 10</td>', 'I love the shadow and the highlights.Sensual, pleasing, technicaly 100% IMHO.Going into my favs...Sorry I cant vote 11 so you have to do with 10', '2005-03-27 19:17:20.000000', NULL, 1),
(1252798, 158049, 17507, '<td valign="top">Image could stand to be a bit sharper, but I really like the tight crop around all the elements in the image. It adds to the tension created by the fact that there''s a dude on a motorcycle in mid-air. Nice work. (7)</td>', 'Image could stand to be a bit sharper, but I really like the tight crop around all the elements in the image. It adds to the tension created by the fact that there''s a dude on a motorcycle in mid-air. Nice work. (7)', '2005-03-27 19:34:15.000000', NULL, 1);
