(1254254, 157584, 29779, '<td valign="top">Verry beautiful photograph. Utha must be beautiful plase to explore. This Canyonlands National Park have to see. Congratulation.</td>', 'Verry beautiful photograph. Utha must be beautiful plase to explore. This Canyonlands National Park have to see. Congratulation.', '2005-03-28 13:35:00.000000', NULL, 0),
(1254279, 158188, 33652, '<td valign="top">Congratulations on your well deserved high placement. Wonderfully powerful image.<br/> <br/>Paula</td>', 'Congratulations on your well deserved high placement. Wonderfully powerful image. Paula', '2005-03-28 13:47:27.000000', NULL, 0),
(1254282, 157584, 32672, '<td valign="top">That''s breathtaking.  I mean, the Grand Canyon (I''m assuming the photo is of that), is gorgeous. but so many photographs of it are pretty, yes, but so cliche.  They all seem to be taken while standing on one cliff, with another cliff off about a football field away as the subject, and then the opposite side of the canyon making the background.<br/>Your photo is different because it adds in a foreground.  Throwing in that new element totally puts this head and shoulders above your regular pretty canyon shot.  Well done!</td>', 'That''s breathtaking.  I mean, the Grand Canyon (I''m assuming the photo is of that), is gorgeous. but so many photographs of it are pretty, yes, but so cliche.  They all seem to be taken while standing on one cliff, with another cliff off about a football field away as the subject, and then the opposite side of the canyon making the background.Your photo is different because it adds in a foreground.  Throwing in that new element totally puts this head and shoulders above your regular pretty canyon shot.  Well done!', '2005-03-28 13:49:09.000000', NULL, 0),
(1254340, 158188, 8367, '<td valign="top">Congratulations on this beautiful capture and a ribbon, Woo Hoo!!<br/>Excellent work! I love the lighting.</td>', 'Congratulations on this beautiful capture and a ribbon, Woo Hoo!!Excellent work! I love the lighting.', '2005-03-28 14:21:39.000000', NULL, 0),
(1254372, 157584, 35274, '<td valign="top">Amazing!! The DOF is pin sharp! One of the most beautiful photos I''ve seen in a while. I would buy it in a heart-beat, good job.</td>', 'Amazing!! The DOF is pin sharp! One of the most beautiful photos I''ve seen in a while. I would buy it in a heart-beat, good job.', '2005-03-28 14:46:16.000000', NULL, 0),
(1254429, 158075, 8367, '<td valign="top">Beautiful image. Congratulations on your blue ribbon!<br/>This is a wonderful capture...and let''s hear it for the kit lens! Hooray!</td>', 'Beautiful image. Congratulations on your blue ribbon!This is a wonderful capture...and let''s hear it for the kit lens! Hooray!', '2005-03-28 15:19:03.000000', NULL, 0),
(1254445, 158075, 17203, '<td valign="top">Congratulations on your blue ribbon, Nikolai! You now have the highest-scoring shot ever for the Canon Digital Rebel, a title that I held for all of one week (gee, thanks). It''s amusing to note that I stood in the very same spot at Torrey Pines just last month. ;-)<br/><br/><i>Message edited by author 2005-03-28 14:35:29.</i></td>', 'Congratulations on your blue ribbon, Nikolai! You now have the highest-scoring shot ever for the Canon Digital Rebel, a title that I held for all of one week (gee, thanks). It''s amusing to note that I stood in the very same spot at Torrey Pines just last month. ;-)', '2005-03-28 15:32:50.000000', '2005-03-28 15:35:29.000000', 0),
